// Dernier compte connu lors du dernier scan_database.py --merge sur projet-14-filiation
// (18e-19e commit, 2026-08-21 : erp_migre + public_marts + raw = 23 tables). A mettre a
// jour manuellement apres chaque nouvelle extraction reelle -- ce workflow ne peut pas
// ecrire dans index.html lui-meme (pas d'acces au poste de Valentin depuis ce conteneur),
// il se contente de signaler qu'une extraction manuelle est probablement necessaire.
const BASELINE = 23;

const total = Number($input.first().json.n_tables);
const drifted = total !== BASELINE;
const message = drifted
  ? `\u26a0\ufe0f Filiation : derive structurelle detectee sur bv-postgres-dbtdev (erp_migre/public_marts/raw) \u2014 ${total} table(s) au lieu de ${BASELINE} attendues lors du dernier scan_database.py. Rejouer 'python scripts/scan_database.py --merge' sur projet-14-filiation, puis committer index.html.`
  : `\u2705 Filiation : structure de bv-postgres-dbtdev inchangee (${total} table(s), conforme au dernier scan du ${BASELINE === total ? '21/08' : '?'}).`;

return [{ json: { total, baseline: BASELINE, drifted, message } }];
